        Question(11016, "Qui a reçu le prix Turing 2023?", listOf("Geoffrey Hinton", "Demis Hassabis", "Paul Cohen", "Richard Karp"), 0, "Technologie", Difficulty.HARD, explanation = "Geoffrey Hinton a reçu le prix Turing 2023 pour ses travaux pionniers sur les réseaux de neurones et l'apprentissage profond, qui ont révolutionné l'intelligence artificielle."),
