        Question(11022, "Qu'est-ce que l'intelligence artificielle?", listOf("La simulation de l'intelligence humaine par des machines", "Un type de robot", "Un langage de programmation", "Un système d'exploitation"), 0, "Technologie", Difficulty.EASY, explanation = "L'intelligence artificielle désigne la capacité des machines à imiter des fonctions cognitives humaines comme l'apprentissage et la résolution de problèmes."),
