        Question(11025, "Qui a inventé la Toile d'araignée mondiale (World Wide Web)?", listOf("Tim Berners-Lee", "Vint Cerf", "Bob Kahn", "Jon Postel"), 0, "Technologie", Difficulty.MEDIUM, explanation = "Tim Berners-Lee a inventé le World Wide Web en 1989 au CERN, proposant un système de documents hypertextes liés par des liens."),
        Question(11026, "Quel est le plus ancien moteur de recherche encore actif?", listOf("AltaVista", "Yahoo", "Google", "Excite"), 1, "Technologie", Difficulty.HARD, explanation = "Yahoo, lancé en 1994 sous le nom \"Jerry and David's Guide to the World Wide Web\", est le plus ancien moteur de recherche encore en activité, bien qu'il ait évolué en portail web."),
