        Question(11029, "Qu'est-ce qu'une adresse IP?", listOf("Un identifiant unique pour un appareil sur internet", "Une alimentation pour ordinateur", "Un type de logiciel", "Une base de données"), 0, "Technologie", Difficulty.MEDIUM, explanation = "Une adresse IP permet d'identifier chaque appareil connecté à un réseau, comme un ordinateur ou un smartphone, pour acheminer correctement les données sur internet."),
        Question(11030, "Quel est le système d'exploitation créé par Google?", listOf("Android", "ChromeOS", "iOS", "Windows"), 0, "Technologie", Difficulty.EASY, explanation = "Android est le système d'exploitation mobile open source développé par Google, principalement utilisé sur les smartphones et tablettes."),
        Question(11031, "En quelle année LinkedIn a-t-il été fondé?", listOf("2003", "2005", "2007", "2009"), 0, "Technologie", Difficulty.MEDIUM, explanation = "LinkedIn a été fondé en décembre 2002 et lancé officiellement le 5 mai 2003."),
        Question(11032, "Qui a créé le langage Ruby?", listOf("Yukihiro Matsumoto", "Guido van Rossum", "Graydon Hoare", "David Heinemeier Hansson"), 0, "Technologie", Difficulty.HARD, explanation = "Yukihiro Matsumoto, souvent appelé Matz, a développé Ruby au Japon dans les années 1990 pour combiner des aspects de ses langages préférés (Perl, Smalltalk, etc.) avec une approche orientée objet."),
        Question(11033, "Qu'est-ce qu'un cache informatique?", listOf("Une mémoire rapide pour stocker les données fréquemment utilisées", "Un fichier temporaire", "Un type d'antivirus", "Un disque dur externe"), 0, "Technologie", Difficulty.HARD, explanation = "Le cache est une mémoire tampon à haute vitesse qui permet d'accélérer l'accès aux données en conservant les informations les plus sollicitées par le processeur ou le navigateur."),
