        Question(11037, "Qu'est-ce que la cybersécurité?", listOf("La protection contre les attaques informatiques", "Un type d'antivirus", "Un langage de programmation", "Un système d'exploitation"), 0, "Technologie", Difficulty.EASY, explanation = "La cybersécurité désigne l'ensemble des pratiques et technologies visant à protéger les systèmes informatiques, réseaux et données contre les accès non autorisés ou les attaques malveillantes."),
