        Question(11039, "En quelle année Intel a-t-il lancé le premier microprocesseur?", listOf("1971", "1975", "1980", "1985"), 0, "Technologie", Difficulty.HARD, explanation = "Le premier microprocesseur commercialisé par Intel, le 4004, a été lancé en 1971, marquant le début de l'ère des microprocesseurs."),
