        Question(11048, "Qu'est-ce qu'une API?", listOf("Une interface de programmation d'application", "Un type de base de données", "Un langage de programmation", "Un système d'exploitation"), 0, "Technologie", Difficulty.MEDIUM, explanation = "Une API (Application Programming Interface) est un ensemble de règles qui permet à des logiciels de communiquer entre eux, comme un serveur de restaurant prenant les commandes entre le client et la cuisine."),
