        Question(11056, "Quel est le langage de programmation créé par Tim Berners-Lee?", listOf("HTML", "JavaScript", "Java", "Python"), 0, "Technologie", Difficulty.MEDIUM, explanation = "Tim Berners-Lee a inventé le HTML en 1990 comme langage de balisage pour structurer les pages web, en parallèle de la création du World Wide Web."),
        Question(11057, "Qu'est-ce que la tokenization en cryptographie?", listOf("La division de données en unités plus petites", "Un type de chiffrement", "Un langage de programmation", "Un système d'exploitation"), 0, "Technologie", Difficulty.HARD, explanation = "En cryptographie, la tokenisation remplace des données sensibles par des jetons uniques, divisant ainsi l'information en unités plus petites et sécurisées pour éviter l'exposition directe des données originales."),
