        Question(11061, "En quelle année Node.js a-t-il été créé?", listOf("2009", "2008", "2010", "2011"), 0, "Technologie", Difficulty.HARD, explanation = "Node.js a été créé en 2009 par Ryan Dahl, qui a présenté le projet lors de la conférence JSConf EU cette année-là."),
