        Question(11063, "Qu'est-ce que l'orchestration de conteneurs?", listOf("La gestion automatisée des conteneurs", "Un type de base de données", "Un langage de programmation", "Un système d'exploitation"), 0, "Technologie", Difficulty.HARD, explanation = "L'orchestration de conteneurs automatise le déploiement, la mise à l'échelle et la gestion des conteneurs, évitant les tâches manuelles complexes."),
