        Question(11066, "Qu'est-ce que GraphQL?", listOf("Un langage de requête pour les APIs", "Un type de base de données", "Un système d'exploitation", "Un langage de programmation"), 0, "Technologie", Difficulty.HARD, explanation = "GraphQL a été créé par Facebook en 2012 pour offrir plus de flexibilité que les APIs REST traditionnelles, permettant aux clients de demander exactement les données dont ils ont besoin."),
        Question(11067, "En quelle année Redis a-t-il été lancé?", listOf("2009", "2008", "2010", "2011"), 0, "Technologie", Difficulty.HARD, explanation = "Redis a été créé par Salvatore Sanfilippo et lancé en 2009. Ce système de gestion de bases de données clé-valeur en mémoire est devenu populaire pour sa rapidité et sa simplicité."),
        Question(11068, "Quel est le créateur de Solidity?", listOf("Gavin Wood", "Vitalik Buterin", "Satoshi Nakamoto", "Charlie Lee"), 0, "Technologie", Difficulty.EXPERT, explanation = "Gavin Wood a proposé le langage Solidity en 2014 pour la plateforme Ethereum, dont il était cofondateur, afin de permettre l'écriture de contrats intelligents."),
        Question(11069, "Qu'est-ce que le hachage cryptographique?", listOf("Une fonction qui convertit des données en une chaîne fixe", "Un type de chiffrement", "Un langage de programmation", "Un système d'exploitation"), 0, "Technologie", Difficulty.HARD, explanation = "Le hachage cryptographique transforme des données de taille variable en une empreinte numérique de taille fixe, utilisée pour vérifier l'intégrité des informations sans révéler leur contenu."),
        Question(11070, "En quelle année Mongoose a-t-il été créé?", listOf("2010", "2009", "2011", "2012"), 0, "Technologie", Difficulty.EXPERT, explanation = "Mongoose, le framework JavaScript pour applications web, a été initialement publié en 2010 par LearnBoost."),
        Question(11071, "Quel est le créateur de Swift?", listOf("Chris Lattner", "Guido van Rossum", "Dennis Ritchie", "Bjarne Stroustrup"), 0, "Technologie", Difficulty.HARD, explanation = "Chris Lattner a conçu Swift chez Apple en 2010, en s'inspirant d'Objective-C, Rust et Haskell, pour remplacer Objective-C dans le développement d'applications iOS et macOS."),
        Question(11072, "Qu'est-ce que la microarchitecture?", listOf("L'architecture interne d'un processeur", "Un type de base de données", "Un langage de programmation", "Un système d'exploitation"), 0, "Technologie", Difficulty.EXPERT, explanation = "La microarchitecture désigne l'organisation interne d'un processeur, incluant ses circuits, pipelines et caches, qui implémente une architecture de jeu d'instructions."),
        Question(11073, "En quelle année Keras a-t-il été lancé?", listOf("2015", "2014", "2016", "2017"), 0, "Technologie", Difficulty.EXPERT, explanation = "Keras a été initialement développé et publié en 2015 par François Chollet, un ingénieur chez Google, dans le but de simplifier la création de réseaux de neurones."),
        Question(11074, "Quel est le créateur de Kotlin?", listOf("JetBrains", "Google", "Facebook", "Microsoft"), 0, "Technologie", Difficulty.HARD, explanation = "Kotlin a été développé par l'entreprise JetBrains, connue pour ses environnements de développement intégrés (IDE) comme IntelliJ IDEA. Le langage a été présenté en 2011 et est devenu un langage officiel pour Android en 2017."),
        Question(11075, "Qu'est-ce que le polymorphisme en programmation?", listOf("La capacité d'un objet à prendre plusieurs formes", "Un type de base de données", "Un système d'exploitation", "Un langage de programmation"), 0, "Technologie", Difficulty.HARD, explanation = "Le polymorphisme permet à des objets de classes différentes de répondre au même appel de méthode de manière spécifique, simplifiant ainsi la gestion de code hétérogène."),
        Question(11076, "En quelle année Spark a-t-il été créé?", listOf("2009", "2008", "2010", "2011"), 0, "Technologie", Difficulty.EXPERT, explanation = "Spark, le framework de traitement de données massives, a été créé en 2009 à l'Université de Californie à Berkeley par Matei Zaharia."),
        Question(11077, "Quel est le créateur de Elixir?", listOf("José Valim", "Guido van Rossum", "Dennis Ritchie", "Bjarne Stroustrup"), 0, "Technologie", Difficulty.EXPERT, explanation = "José Valim a créé Elixir en 2012 pour combiner la productivité de Ruby avec les performances et la concurrence de la machine virtuelle Erlang (BEAM)."),
        Question(11078, "Qu'est-ce que la programmation orientée objet?", listOf("Un paradigme de programmation basé sur des objets", "Un type de base de données", "Un système d'exploitation", "Un langage de programmation"), 0, "Technologie", Difficulty.MEDIUM, explanation = "La programmation orientée objet structure le code en regroupant données et fonctions dans des entités appelées objets, contrairement à la programmation procédurale qui utilise des fonctions et des variables séparées."),
        Question(11079, "En quelle année TensorFlow a-t-il été lancé?", listOf("2015", "2014", "2016", "2017"), 0, "Technologie", Difficulty.EXPERT, explanation = "TensorFlow, la bibliothèque open-source d'apprentissage automatique, a été initialement publiée par Google en 2015."),
        Question(11080, "Quel est le créateur de Groovy?", listOf("James Strachan", "Guido van Rossum", "Dennis Ritchie", "Bjarne Stroustrup"), 0, "Technologie", Difficulty.EXPERT, explanation = "James Strachan a créé Groovy en 2003 en tant que langage de script dynamique pour la plateforme Java. Il l'a conçu pour offrir une syntaxe plus concise et flexible que Java, tout en restant compatible avec ses bibliothèques."),
        Question(11081, "Qu'est-ce que l'encapsulation en programmation?", listOf("La restriction de l'accès aux données internes", "Un type de base de données", "Un système d'exploitation", "Un langage de programmation"), 0, "Technologie", Difficulty.HARD, explanation = "L'encapsulation est un principe fondamental de la programmation orientée objet qui consiste à protéger les données d'un objet en limitant leur accès direct depuis l'extérieur."),
        Question(11082, "En quelle année PyTorch a-t-il été lancé?", listOf("2016", "2015", "2017", "2018"), 0, "Technologie", Difficulty.EXPERT, explanation = "PyTorch a été lancé en septembre 2016 par le laboratoire d'intelligence artificielle de Facebook (FAIR)."),
        Question(11083, "Quel est le créateur de Lua?", listOf("Roberto Ierusalimschy", "Guido van Rossum", "Dennis Ritchie", "Bjarne Stroustrup"), 0, "Technologie", Difficulty.EXPERT, explanation = "Roberto Ierusalimschy a créé Lua en 1993 au Brésil, avec Luiz Henrique de Figueiredo et Waldemar Celes, pour offrir un langage de script léger et embarqué."),
        Question(11084, "Qu'est-ce que l'héritage en programmation?", listOf("La transmission de propriétés d'une classe à une autre", "Un type de base de données", "Un système d'exploitation", "Un langage de programmation"), 0, "Technologie", Difficulty.HARD, explanation = "L'héritage est un concept de la programmation orientée objet où une classe fille hérite des attributs et méthodes d'une classe mère, permettant la réutilisation et l'extension du code."),
        Question(11085, "En quelle année Pandas a-t-il été créé?", listOf("2008", "2007", "2009", "2010"), 0, "Technologie", Difficulty.EXPERT, explanation = "Pandas a été créé en 2008 par Wes McKinney pour répondre aux besoins d'analyse de données financières en Python."),
        Question(11086, "Quel est le créateur de R?", listOf("Ross Ihaka et Robert Gentleman", "Guido van Rossum", "Dennis Ritchie", "Bjarne Stroustrup"), 0, "Technologie", Difficulty.EXPERT, explanation = "Ross Ihaka et Robert Gentleman ont créé le langage R en 1993 à l'Université d'Auckland, en Nouvelle-Zélande, pour offrir une alternative libre au langage S."),
        Question(11087, "Qu'est-ce que le polymorphisme d'héritage?", listOf("Un type de polymorphisme basé sur l'héritage", "Une base de données", "Un système d'exploitation", "Un langage de programmation"), 0, "Technologie", Difficulty.EXPERT, explanation = "Le polymorphisme d'héritage permet à une classe fille de redéfinir le comportement d'une méthode héritée, tout en conservant l'interface de la classe parente."),
        Question(11088, "En quelle année Seaborn a-t-il été lancé?", listOf("2012", "2011", "2013", "2014"), 0, "Technologie", Difficulty.EXPERT, explanation = "Seaborn, une bibliothèque de visualisation de données pour Python, a été lancée en 2012 par Michael Waskom."),
        Question(11089, "Quel est le créateur de MATLAB?", listOf("Cleve Moler", "Guido van Rossum", "Dennis Ritchie", "Bjarne Stroustrup"), 0, "Technologie", Difficulty.EXPERT, explanation = "Cleve Moler a créé MATLAB dans les années 1970 pour donner aux étudiants un accès facile aux bibliothèques LINPACK et EISPACK, sans avoir à écrire de code Fortran."),
        Question(11090, "Qu'est-ce que la programmation fonctionnelle?", listOf("Un paradigme basé sur des fonctions mathématiques", "Un type de base de données", "Un système d'exploitation", "Un langage de programmation"), 0, "Technologie", Difficulty.HARD, explanation = "La programmation fonctionnelle traite les calculs comme l'évaluation de fonctions mathématiques, évitant les changements d'état et les données mutables, contrairement à la programmation impérative."),
        Question(11091, "En quelle année SciPy a-t-il été créé?", listOf("2001", "2000", "2002", "2003"), 0, "Technologie", Difficulty.EXPERT, explanation = "SciPy a été créé en 2001 par Travis Oliphant, Pearu Peterson et Eric Jones comme bibliothèque open source pour le calcul scientifique en Python."),
        Question(11092, "Quel est le créateur de Fortran?", listOf("John Backus", "Guido van Rossum", "Dennis Ritchie", "Bjarne Stroustrup"), 0, "Technologie", Difficulty.EXPERT, explanation = "John Backus a dirigé l'équipe d'IBM qui a développé Fortran, le premier langage de programmation de haut niveau, lancé en 1957."),
        Question(11093, "Qu'est-ce que le pattern strategy?", listOf("Un modèle de conception pour les stratégies", "Un type de base de données", "Un système d'exploitation", "Un langage de programmation"), 0, "Technologie", Difficulty.HARD, explanation = "Le pattern Strategy est un modèle de conception qui permet de définir une famille d'algorithmes, de les encapsuler et de les rendre interchangeables, sans modifier le code client."),
        Question(11094, "En quelle année NumPy a-t-il été lancé?", listOf("2006", "2005", "2007", "2008"), 0, "Technologie", Difficulty.EXPERT, explanation = "NumPy a été initialement publié en 2006, succédant à Numeric et Numarray, pour unifier la communauté du calcul numérique en Python."),
        Question(11095, "Quel est le créateur de Ada?", listOf("Jean Ichbiah", "Guido van Rossum", "Dennis Ritchie", "Bjarne Stroustrup"), 0, "Technologie", Difficulty.EXPERT, explanation = "Jean Ichbiah a dirigé l'équipe qui a conçu le langage de programmation Ada dans les années 1970, sous contrat avec le département de la Défense américain."),
        Question(11096, "Qu'est-ce que le pattern factory?", listOf("Un modèle de création d'objets", "Un type de base de données", "Un système d'exploitation", "Un langage de programmation"), 0, "Technologie", Difficulty.HARD, explanation = "Le pattern factory est un patron de conception logicielle qui encapsule la logique d'instanciation d'objets, permettant de déléguer la création à des classes spécialisées."),
        Question(11097, "En quelle année Scikit-learn a-t-il été créé?", listOf("2007", "2006", "2008", "2009"), 0, "Technologie", Difficulty.EXPERT, explanation = "Scikit-learn a été initialement développé par David Cournapeau en 2007 dans le cadre d'un projet Google Summer of Code."),
        Question(11098, "Quel est le créateur de Modula?", listOf("Niklaus Wirth", "Guido van Rossum", "Dennis Ritchie", "Bjarne Stroustrup"), 0, "Technologie", Difficulty.EXPERT, explanation = "Niklaus Wirth a créé le langage de programmation Modula en 1977, après avoir développé Pascal, en y ajoutant des concepts de modularité et de programmation concurrente."),
        Question(11099, "Qu'est-ce que le pattern observer?", listOf("Un modèle de comportement d'observation", "Un type de base de données", "Un système d'exploitation", "Un langage de programmation"), 0, "Technologie", Difficulty.HARD, explanation = "Le pattern observer est un modèle de conception logicielle où un objet (le sujet) notifie automatiquement une liste d'observateurs de ses changements d'état, sans les coupler étroitement."),
        Question(11100, "Quel est le créateur du langage Lua?", listOf("Roberto Ierusalimschy", "Guido van Rossum", "Dennis Ritchie", "Bjarne Stroustrup"), 0, "Technologie", Difficulty.EXPERT, explanation = "Roberto Ierusalimschy a conçu Lua au Brésil en 1993, avec Luiz Henrique de Figueiredo et Waldemar Celes, pour répondre aux besoins de flexibilité et d'extensibilité dans les applications."),
        Question(11101, "Qu'est-ce que la mémoire cache L1?", listOf("La mémoire cache la plus rapide d'un processeur", "Un type de base de données", "Un système d'exploitation", "Un langage de programmation"), 0, "Technologie", Difficulty.HARD, explanation = "La mémoire cache L1 est intégrée directement dans le cœur du processeur, ce qui la rend plus rapide que les caches L2 et L3, car elle minimise les délais d'accès aux données fréquemment utilisées."),
        Question(11102, "Quel est le créateur de Clojure?", listOf("Rich Hickey", "Guido van Rossum", "Dennis Ritchie", "Bjarne Stroustrup"), 0, "Technologie", Difficulty.EXPERT, explanation = "Rich Hickey a créé Clojure en 2007 comme un dialecte moderne de Lisp fonctionnant sur la machine virtuelle Java, visant la concurrence et la simplicité."),
        Question(11103, "Qu'est-ce que un interrupt en informatique?", listOf("Un signal d'arrêt envoyé au processeur", "Un type de base de données", "Un système d'exploitation", "Un langage de programmation"), 0, "Technologie", Difficulty.HARD, explanation = "Un interrupt est un signal matériel ou logiciel qui interrompt le processeur dans sa tâche en cours pour lui demander de traiter un événement urgent, comme une frappe au clavier ou une opération d'entrée-sortie terminée."),
        Question(11104, "Quel est le créateur de Haskell?", listOf("Simon Peyton Jones et al.", "Guido van Rossum", "Dennis Ritchie", "Bjarne Stroustrup"), 0, "Technologie", Difficulty.EXPERT, explanation = "Simon Peyton Jones est le principal concepteur de Haskell, un langage de programmation fonctionnel standardisé en 1990, développé avec d'autres chercheurs."),
        Question(11105, "Qu'est-ce que la gestion de la mémoire?", listOf("Le contrôle de l'utilisation de la mémoire RAM", "Un type de base de données", "Un système d'exploitation", "Un langage de programmation"), 0, "Technologie", Difficulty.MEDIUM, explanation = "La gestion de la mémoire désigne les mécanismes par lesquels un système d'exploitation alloue et libère la RAM entre les programmes en cours d'exécution pour optimiser les performances et éviter les conflits."),
        Question(11106, "Quel est le créateur de OCaml?", listOf("Xavier Leroy", "Guido van Rossum", "Dennis Ritchie", "Bjarne Stroustrup"), 0, "Technologie", Difficulty.EXPERT, explanation = "Xavier Leroy a conçu et implémenté le langage OCaml à l'Inria dans les années 1990, en tant que successeur du langage Caml."),
        Question(11107, "Qu'est-ce qu'une table de hachage?", listOf("Une structure de données utilisant le hachage", "Un type de base de données", "Un système d'exploitation", "Un langage de programmation"), 0, "Technologie", Difficulty.HARD, explanation = "Une table de hachage associe des clés à des valeurs via une fonction de hachage, permettant un accès rapide aux données."),
        Question(11108, "Quel est le créateur de Scheme?", listOf("Guy Lewis Steele Jr.", "Guido van Rossum", "Dennis Ritchie", "Bjarne Stroustrup"), 0, "Technologie", Difficulty.EXPERT, explanation = "Guy Lewis Steele Jr. a co-créé le langage de programmation Scheme avec Gerald Jay Sussman au MIT dans les années 1970, en s'inspirant du lambda-calcul d'Alonzo Church."),
        Question(11109, "Qu'est-ce qu'un arbre binaire?", listOf("Une structure de données arborescente avec deux enfants max", "Un type de base de données", "Un système d'exploitation", "Un langage de programmation"), 0, "Technologie", Difficulty.HARD, explanation = "En informatique, un arbre binaire est une structure de données où chaque nœud a au plus deux enfants, appelés fils gauche et fils droit, ce qui permet de représenter des hiérarchies et d'optimiser les recherches."),
        Question(11110, "Quel est le créateur de Objective-C?", listOf("Brad Cox et Tom Love", "Guido van Rossum", "Dennis Ritchie", "Bjarne Stroustrup"), 0, "Technologie", Difficulty.EXPERT, explanation = "Objective-C a été créé par Brad Cox et Tom Love au début des années 1980 chez Stepstone, en ajoutant des fonctionnalités orientées objet au langage C."),
        Question(11111, "Qu'est-ce qu'une queue de priorité?", listOf("Une structure où les éléments sont ordonnés par priorité", "Un type de base de données", "Un système d'exploitation", "Un langage de programmation"), 0, "Technologie", Difficulty.HARD, explanation = "Une file de priorité est une structure de données où chaque élément possède une priorité, et l'élément avec la plus haute priorité est toujours retiré en premier."),
        Question(11112, "Quel est le créateur de Eiffel?", listOf("Bertrand Meyer", "Guido van Rossum", "Dennis Ritchie", "Bjarne Stroustrup"), 0, "Technologie", Difficulty.EXPERT, explanation = "Bertrand Meyer a conçu le langage de programmation Eiffel en 1985, en mettant l'accent sur la conception par contrat et la fiabilité logicielle."),
        Question(11113, "Qu'est-ce que la complexité algorithmique?", listOf("L'étude de la performance des algorithmes", "Un type de base de données", "Un système d'exploitation", "Un langage de programmation"), 0, "Technologie", Difficulty.HARD, explanation = "La complexité algorithmique évalue l'efficacité d'un algorithme en fonction du temps ou de la mémoire nécessaire selon la taille des données."),
        Question(11114, "Quel est le créateur de Smalltalk?", listOf("Alan Kay", "Guido van Rossum", "Dennis Ritchie", "Bjarne Stroustrup"), 0, "Technologie", Difficulty.EXPERT, explanation = "Alan Kay a conçu le langage Smalltalk dans les années 1970 au Xerox PARC, posant les bases de la programmation orientée objet moderne."),
        Question(11115, "Qu'est-ce qu'une liste chaînée?", listOf("Une structure où les éléments sont chaînés entre eux", "Un type de base de données", "Un système d'exploitation", "Un langage de programmation"), 0, "Technologie", Difficulty.MEDIUM, explanation = "En informatique, une liste chaînée est une structure de données linéaire où chaque élément, appelé nœud, contient une valeur et un pointeur vers le nœud suivant."),
        Question(11116, "Quel est le créateur de Simula?", listOf("Ole-Johan Dahl et Kristen Nygaard", "Guido van Rossum", "Dennis Ritchie", "Bjarne Stroustrup"), 0, "Technologie", Difficulty.EXPERT, explanation = "Ole-Johan Dahl et Kristen Nygaard ont conçu Simula dans les années 1960 chez le Centre de calcul norvégien, posant les bases de la programmation orientée objet."),
        Question(11117, "Qu'est-ce que le tri rapide?", listOf("Un algorithme de tri basé sur le partitionnement", "Un type de base de données", "Un système d'exploitation", "Un langage de programmation"), 0, "Technologie", Difficulty.HARD, explanation = "Le tri rapide (ou quicksort) est un algorithme de tri efficace qui fonctionne en choisissant un pivot et en partitionnant le tableau en éléments plus petits et plus grands."),
        Question(11118, "Quel est le créateur de Algol?", listOf("Un groupe international de scientifiques", "Guido van Rossum", "Dennis Ritchie", "Bjarne Stroustrup"), 0, "Technologie", Difficulty.EXPERT, explanation = "Algol a été conçu par un comité international de scientifiques réunis pour créer un langage de programmation universel, et non par un individu seul."),
        Question(11119, "Qu'est-ce que le tri fusion?", listOf("Un algorithme de tri basé sur la division et fusion", "Un type de base de données", "Un système d'exploitation", "Un langage de programmation"), 0, "Technologie", Difficulty.HARD, explanation = "Le tri fusion est un algorithme récursif qui divise une liste en sous-listes jusqu'à ce qu'elles soient triées, puis les fusionne pour obtenir une liste ordonnée."),
        Question(11120, "Qui a créé Minecraft?", listOf("Notch (Markus Persson)", "Johan Säfström", "Jens Bergensten", "Daniel Rosenfeld"), 0, "Technologie", Difficulty.EASY, explanation = "Markus Persson, connu sous le pseudo Notch, a développé la première version de Minecraft en 2009 avant de fonder Mojang."),
        Question(11121, "En quelle année Minecraft a-t-il été lancé?", listOf("2009", "2008", "2010", "2011"), 0, "Technologie", Difficulty.MEDIUM, explanation = "Minecraft a été rendu public pour la première fois le 17 mai 2009 en tant que version alpha développée par Markus Persson."),
        Question(11122, "Quel est le moteur de jeu créé par Epic Games?", listOf("Unreal Engine", "Unity", "Godot", "CryEngine"), 0, "Technologie", Difficulty.EASY, explanation = "Epic Games a développé Unreal Engine, lancé en 1998 avec le jeu Unreal, et il est devenu un moteur de jeu très utilisé dans l'industrie du jeu vidéo et au-delà."),
        Question(11123, "En quelle année le moteur Unity a-t-il été lancé?", listOf("2005", "2003", "2007", "2009"), 0, "Technologie", Difficulty.MEDIUM, explanation = "Unity Technologies a présenté la première version du moteur Unity lors de la conférence Apple Worldwide Developers Conference en 2005, initialement conçu pour les jeux Mac OS X."),
        Question(11124, "Qui a créé Fortnite?", listOf("Epic Games", "Activision", "Ubisoft", "EA Games"), 0, "Technologie", Difficulty.EASY, explanation = "Epic Games, entreprise américaine fondée par Tim Sweeney, a développé et publié Fortnite en 2017. Le jeu est devenu un phénomène mondial grâce à son mode Battle Royale gratuit."),
        Question(11125, "Quel est le créateur de The Legend of Zelda?", listOf("Shigeru Miyamoto", "Satoru Iwata", "Gunpei Yokoi", "Hiroshi Yamauchi"), 0, "Technologie", Difficulty.MEDIUM, explanation = "Shigeru Miyamoto a créé The Legend of Zelda en 1986, s'inspirant de ses explorations enfantines dans la campagne japonaise. Il est également le créateur de Super Mario."),
        Question(11126, "En quelle année le PlayStation 5 a-t-il été lancé?", listOf("2020", "2019", "2021", "2022"), 0, "Technologie", Difficulty.EASY, explanation = "La PlayStation 5 a été lancée en novembre 2020, succédant à la PlayStation 4 après sept ans de commercialisation."),
        Question(11127, "Quel studio a créé God of War?", listOf("Santa Monica Studio", "Naughty Dog", "Insomniac Games", "Guerrilla Games"), 0, "Technologie", Difficulty.MEDIUM, explanation = "Santa Monica Studio, filiale de Sony Interactive Entertainment, a développé la série God of War depuis son premier opus en 2005."),
        Question(11128, "En quelle année Steam a-t-il été lancé?", listOf("2003", "2001", "2005", "2007"), 0, "Technologie", Difficulty.MEDIUM, explanation = "Steam a été lancé par Valve en septembre 2003, initialement comme plateforme de mise à jour automatique pour ses jeux, avant de devenir le principal magasin de jeux PC."),
        Question(11129, "Quel jeu vidéo a remporté le Game of the Year 2023?", listOf("Baldur's Gate 3", "Alan Wake 2", "Starfield", "Spider-Man 2"), 0, "Technologie", Difficulty.MEDIUM, explanation = "Baldur's Gate 3, développé par Larian Studios, a remporté le Game of the Year 2023 aux Game Awards grâce à son gameplay profond et sa narration immersive."),
        Question(11130, "Qui a créé le concept de réalité virtuelle?", listOf("Jaron Lanier", "Mark Zuckerberg", "Steve Jobs", "Bill Gates"), 0, "Technologie", Difficulty.HARD, explanation = "Jaron Lanier a popularisé le terme « réalité virtuelle » dans les années 1980 et a fondé VPL Research, la première entreprise à vendre des casques et gants de réalité virtuelle."),
        Question(11131, "Quel est le langage utilisé pour les scripts dans Unity?", listOf("C#", "C++", "Java", "Python"), 0, "Technologie", Difficulty.MEDIUM, explanation = "Unity utilise principalement C# comme langage de script, car il offre une intégration native avec le moteur et une syntaxe adaptée au développement de jeux."),
        Question(11132, "En quelle année le Oculus Rift a-t-il été lancé?", listOf("2016", "2014", "2018", "2020"), 0, "Technologie", Difficulty.MEDIUM, explanation = "L'Oculus Rift, premier casque de réalité virtuelle grand public de la marque, a été commercialisé en mars 2016 après une campagne de financement participatif en 2012 et des versions développeurs."),
        Question(11133, "Quel studio a créé la série Halo?", listOf("Bungie", "343 Industries", "Gearbox Software", "Obsidian Entertainment"), 1, "Technologie", Difficulty.MEDIUM, explanation = "343 Industries a repris le développement de la série Halo en 2007, succédant à Bungie, et a produit la plupart des jeux principaux depuis Halo 4."),
        Question(11134, "En quelle année Roblox a-t-il été fondé?", listOf("2004", "2002", "2006", "2008"), 0, "Technologie", Difficulty.HARD, explanation = "Roblox a été fondé en 2004 par David Baszucki et Erik Cassel, initialement sous le nom de Dynablocks avant d'être renommé en 2005."),
        Question(11135, "Quel est le moteur de jeu utilisé par Fortnite?", listOf("Unreal Engine 4", "Unity", "Godot", "CryEngine"), 0, "Technologie", Difficulty.MEDIUM, explanation = "Fortnite est développé par Epic Games, qui est aussi le créateur d'Unreal Engine, leur moteur de jeu propriétaire utilisé pour le titre."),
        Question(11136, "En quelle année le premier jeu vidéo commercial a-t-il été lancé?", listOf("1972", "1970", "1974", "1976"), 0, "Technologie", Difficulty.HARD, explanation = "Le premier jeu vidéo commercial, Pong, a été lancé par Atari en 1972. Ce jeu de tennis simplifié a marqué le début de l'industrie vidéoludique grand public."),
        Question(11137, "Quel jeu vidéo a été le premier à vendre 100 millions de copies?", listOf("Tetris", "Super Mario Bros", "Wii Sports", "Minecraft"), 0, "Technologie", Difficulty.HARD, explanation = "Tetris a atteint ce cap historique grâce à ses innombrables versions sur consoles, mobiles et ordinateurs depuis sa création en 1984, cumulant plus de 520 millions de téléchargements payants."),
        Question(11138, "En quelle année le PlayStation a-t-il été lancé?", listOf("1994", "1992", "1996", "1998"), 0, "Technologie", Difficulty.MEDIUM, explanation = "La PlayStation originale a été lancée au Japon le 3 décembre 1994, marquant l'entrée de Sony sur le marché des consoles de salon."),
        Question(11139, "Quel est le créateur de Pokémon?", listOf("Ken Sugimori et Satoshi Tajiri", "Shigeru Miyamoto", "Gunpei Yokoi", "Hiroshi Yamauchi"), 0, "Technologie", Difficulty.MEDIUM, explanation = "Satoshi Tajiri a imaginé Pokémon en 1996, inspiré par son enfance à collectionner des insectes, tandis que Ken Sugimori a conçu les premiers dessins des créatures."),
        Question(11140, "En quelle année le Nintendo Switch a-t-il été lancé?", listOf("2017", "2015", "2019", "2021"), 0, "Technologie", Difficulty.EASY, explanation = "La Nintendo Switch a été lancée mondialement en mars 2017, succédant à la Wii U et marquant un retour réussi pour Nintendo avec son concept hybride console portable et de salon."),
        Question(11141, "Quel est le plus grand éditeur de jeux vidéo au monde?", listOf("Tencent", "Sony", "Microsoft", "Nintendo"), 0, "Technologie", Difficulty.HARD, explanation = "Tencent est le plus grand éditeur de jeux vidéo au monde en termes de revenus, grâce à ses participations dans Riot Games, Epic Games et Supercell."),
        Question(11142, "En quelle année la VR a-t-elle été commercialisée pour la première fois?", listOf("1995", "1990", "2000", "2005"), 0, "Technologie", Difficulty.HARD, explanation = "La première console de réalité virtuelle grand public, la Virtual Boy de Nintendo, a été commercialisée en 1995."),
        Question(11143, "Quel est le jeu vidéo le plus joué au monde?", listOf("PUBG", "Fortnite", "League of Legends", "Minecraft"), 0, "Technologie", Difficulty.HARD, explanation = "PUBG a détenu le record du nombre de joueurs simultanés sur Steam et a été un pionnier du battle royale, atteignant des centaines de millions de joueurs cumulés."),
        Question(11144, "En quelle année Twitch a-t-il été fondé?", listOf("2011", "2009", "2013", "2015"), 0, "Technologie", Difficulty.MEDIUM, explanation = "Twitch est né en 2011 sous le nom de Justin.tv, avant de se recentrer uniquement sur le jeu vidéo en direct et de prendre son nom actuel."),
        Question(11145, "Quel est le studio créateur de The Witcher?", listOf("CD Projekt Red", "Obsidian Entertainment", "BioWare", "Bethesda Game Studios"), 0, "Technologie", Difficulty.MEDIUM, explanation = "CD Projekt Red, studio polonais fondé en 2002, a développé la série de jeux The Witcher, adaptée des romans d'Andrzej Sapkowski."),
        Question(11146, "En quelle année Discord a-t-il été lancé?", listOf("2015", "2013", "2017", "2019"), 0, "Technologie", Difficulty.MEDIUM, explanation = "Discord a été lancé en 2015 par Jason Citron et Stanislav Vishnevskiy, initialement conçu pour les joueurs afin de communiquer vocalement pendant les parties."),
        Question(11147, "Quel est le créateur de League of Legends?", listOf("Riot Games", "Blizzard Entertainment", "Valve", "Activision"), 0, "Technologie", Difficulty.MEDIUM, explanation = "Riot Games a développé et publié League of Legends en 2009, devenant ainsi le créateur officiel du jeu."),
        Question(11148, "En quelle année Counter-Strike a-t-il été lancé?", listOf("2000", "1998", "2002", "2004"), 0, "Technologie", Difficulty.HARD, explanation = "Counter-Strike est sorti en 2000 en tant que mod pour Half-Life, avant d'être racheté par Valve et de devenir un jeu à part entière."),
        Question(11149, "Quel est le plus ancien jeu vidéo encore joué?", listOf("Pong", "Space Invaders", "Pac-Man", "Tetris"), 0, "Technologie", Difficulty.HARD, explanation = "Pong, sorti en 1972 sur borne d'arcade, est souvent considéré comme le premier jeu vidéo grand public et reste jouable aujourd'hui via des émulateurs ou des rééditions."),
        Question(11150, "Qui a inventé l'ampoule électrique?", listOf("Thomas Edison", "Nikola Tesla", "Joseph Swan", "Humphry Davy"), 0, "Technologie", Difficulty.EASY, explanation = "Thomas Edison a commercialisé la première ampoule électrique pratique en 1879, mais il s'est appuyé sur les travaux de nombreux prédécesseurs comme Joseph Swan."),
        Question(11151, "En quelle année l'ampoule électrique a-t-elle été inventée?", listOf("1879", "1875", "1883", "1887"), 0, "Technologie", Difficulty.MEDIUM, explanation = "Thomas Edison a présenté la première ampoule électrique pratique à incandescence en 1879, après des années d'expérimentation."),
        Question(11152, "Qui a inventé le téléphone?", listOf("Alexander Graham Bell", "Nikola Tesla", "Thomas Edison", "Samuel Morse"), 0, "Technologie", Difficulty.EASY, explanation = "Alexander Graham Bell a déposé le brevet du téléphone en 1876, bien que l'italien Antonio Meucci ait développé un prototype similaire plus tôt."),
        Question(11153, "En quelle année le téléphone a-t-il été inventé?", listOf("1876", "1872", "1880", "1884"), 0, "Technologie", Difficulty.MEDIUM, explanation = "Alexander Graham Bell a déposé le brevet du téléphone le 7 mars 1876, marquant l'invention officielle de cet appareil de communication."),
        Question(11154, "Qui a inventé la radio?", listOf("Guglielmo Marconi", "Nikola Tesla", "Thomas Edison", "Alexander Graham Bell"), 0, "Technologie", Difficulty.MEDIUM, explanation = "Guglielmo Marconi a réalisé la première transmission radio transatlantique en 1901, ce qui lui a valu le prix Nobel de physique en 1909."),
        Question(11155, "En quelle année la radio a-t-elle été inventée?", listOf("1895", "1891", "1899", "1903"), 0, "Technologie", Difficulty.HARD, explanation = "Guglielmo Marconi réalisa la première transmission radio réussie en 1895, marquant l'invention de la radio. Cette avancée technologique permit la communication sans fil à distance."),
        Question(11156, "Qui a inventé la télévision?", listOf("Vladimir Zworykin", "Philo Farnsworth", "Paul Nipkow", "John Logie Baird"), 0, "Technologie", Difficulty.HARD, explanation = "Vladimir Zworykin a déposé le brevet du premier tube cathodique entièrement électronique en 1923, posant les bases de la télévision moderne."),
        Question(11157, "En quelle année la télévision a-t-elle été inventée?", listOf("1927", "1923", "1931", "1935"), 0, "Technologie", Difficulty.HARD, explanation = "L'invention du premier système de télévision électronique fonctionnel est attribuée à Philo Farnsworth, qui a transmis la première image en 1927."),
        Question(11158, "Qui a inventé le transistor?", listOf("John Bardeen, Léon Cooper et Robert Schrieffer", "Nikola Tesla", "Thomas Edison", "Alexander Graham Bell"), 1, "Technologie", Difficulty.HARD, explanation = "Nikola Tesla n'a pas inventé le transistor. Le transistor a été inventé en 1947 par John Bardeen, Walter Brattain et William Shockley chez Bell Labs."),
        Question(11159, "En quelle année le transistor a-t-il été inventé?", listOf("1947", "1943", "1951", "1955"), 0, "Technologie", Difficulty.HARD, explanation = "Le transistor a été inventé en 1947 par les physiciens John Bardeen, Walter Brattain et William Shockley aux laboratoires Bell, marquant une révolution dans l'électronique."),
        Question(11160, "Qui a inventé le circuit intégré?", listOf("Jack Kilby et Robert Noyce", "Nikola Tesla", "Thomas Edison", "Alexander Graham Bell"), 0, "Technologie", Difficulty.HARD, explanation = "Jack Kilby, chez Texas Instruments, a créé le premier circuit intégré en 1958, tandis que Robert Noyce, chez Fairchild Semiconductor, a développé une version plus pratique en silicium en 1959."),
        Question(11161, "En quelle année le circuit intégré a-t-il été inventé?", listOf("1958", "1954", "1962", "1966"), 0, "Technologie", Difficulty.HARD, explanation = "Le premier circuit intégré a été inventé en 1958 par Jack Kilby chez Texas Instruments, révolutionnant l'électronique en miniaturisant les composants sur une seule puce de silicium."),
        Question(11162, "Qui a inventé le microprocesseur?", listOf("Intel (Ted Hoff, Federico Faggin)", "Motorola", "AMD", "Zilog"), 0, "Technologie", Difficulty.HARD, explanation = "Ted Hoff, ingénieur chez Intel, a conçu l'architecture du premier microprocesseur, le 4004, en 1971, et Federico Faggin l'a réalisé en circuits intégrés."),
        Question(11163, "En quelle année le microprocesseur a-t-il été inventé?", listOf("1971", "1967", "1975", "1979"), 0, "Technologie", Difficulty.HARD, explanation = "Le premier microprocesseur, l'Intel 4004, a été commercialisé en 1971, marquant une révolution en intégrant l'unité centrale d'un ordinateur sur une seule puce."),
        Question(11164, "Qui a inventé le disque dur?", listOf("IBM", "Seagate", "Western Digital", "Maxtor"), 0, "Technologie", Difficulty.HARD, explanation = "IBM a présenté le premier disque dur, le RAMAC 305, en 1956. Cette invention a révolutionné le stockage de données en permettant un accès aléatoire aux informations."),
        Question(11165, "En quelle année le disque dur a-t-il été inventé?", listOf("1956", "1952", "1960", "1964"), 0, "Technologie", Difficulty.HARD, explanation = "Le premier disque dur, le IBM 350 RAMAC, a été inventé en 1956 par IBM. Il stockait 5 Mo de données sur 50 plateaux de 24 pouces."),
        Question(11166, "Qui a inventé le laser?", listOf("Theodore Maiman", "Charles H. Townes", "Gordon Gould", "Albert Einstein"), 0, "Technologie", Difficulty.HARD, explanation = "Theodore Maiman a construit le premier laser fonctionnel en 1960 au laboratoire Hughes Research, utilisant un cristal de rubis synthétique."),
        Question(11167, "En quelle année le laser a-t-il été inventé?", listOf("1960", "1956", "1964", "1968"), 0, "Technologie", Difficulty.HARD, explanation = "Le premier laser fonctionnel a été créé en 1960 par Theodore Maiman, utilisant un cristal de rubis synthétique. Cette invention a marqué le début d'une nouvelle ère dans les technologies optiques."),
        Question(11168, "Qui a inventé les codes-barres?", listOf("Bernard Silver et Norman Joseph Woodland", "Nikola Tesla", "Thomas Edison", "Alexander Graham Bell"), 0, "Technologie", Difficulty.HARD, explanation = "Bernard Silver et Norman Joseph Woodland ont breveté le premier code-barres en 1952, inspiré par le code Morse, pour automatiser la lecture des produits en magasin."),
        Question(11169, "En quelle année les codes-barres ont-ils été inventés?", listOf("1952", "1948", "1956", "1960"), 0, "Technologie", Difficulty.HARD, explanation = "Les codes-barres ont été inventés en 1952 par Norman Woodland et Bernard Silver, qui ont déposé un brevet pour un système de lecture optique de motifs linéaires."),
        Question(11170, "Qui a inventé la fibre optique?", listOf("Charles K. Kao", "John Tyndall", "Alexander Graham Bell", "Guglielmo Marconi"), 0, "Technologie", Difficulty.HARD, explanation = "Charles K. Kao a posé les bases théoriques de la transmission de la lumière par fibres de verre dans les années 1960, ce qui lui a valu le prix Nobel de physique en 2009."),
        Question(11171, "En quelle année la fibre optique a-t-elle été inventée?", listOf("1966", "1962", "1970", "1974"), 0, "Technologie", Difficulty.HARD, explanation = "La fibre optique a été inventée en 1966 par les physiciens Charles Kao et George Hockham, qui ont démontré qu'elle pouvait transmettre la lumière sur de longues distances."),
        Question(11172, "Qui a inventé le WiFi?", listOf("IEEE 802.11", "Nikola Tesla", "Thomas Edison", "Alexander Graham Bell"), 0, "Technologie", Difficulty.HARD, explanation = "Le Wi-Fi est basé sur la norme IEEE 802.11, développée par l'Institute of Electrical and Electronics Engineers (IEEE). Aucun inventeur unique n'est à l'origine du Wi-Fi, mais un comité de l'IEEE a standardisé cette technologie en 1997."),
        Question(11173, "En quelle année le WiFi a-t-il été inventé?", listOf("1997", "1993", "2001", "2005"), 0, "Technologie", Difficulty.HARD, explanation = "Le protocole WiFi a été standardisé en 1997 par l'IEEE sous la norme 802.11, permettant les premières communications sans fil locales."),
        Question(11174, "Qui a inventé le Bluetooth?", listOf("Jaap Haartsen", "Nikola Tesla", "Thomas Edison", "Alexander Graham Bell"), 0, "Technologie", Difficulty.HARD, explanation = "Jaap Haartsen, ingénieur chez Ericsson, a développé la technologie Bluetooth en 1994 pour remplacer les câbles entre appareils."),
        Question(11175, "En quelle année le Bluetooth a-t-il été inventé?", listOf("1994", "1990", "1998", "2002"), 0, "Technologie", Difficulty.HARD, explanation = "Le Bluetooth a été développé en 1994 par Ericsson, une entreprise suédoise de télécommunications, sous la direction de l'ingénieur Jaap Haartsen."),
        Question(11176, "Qui a inventé le GPS?", listOf("Ivan Getting et Robert Easton", "Nikola Tesla", "Thomas Edison", "Alexander Graham Bell"), 0, "Technologie", Difficulty.HARD, explanation = "Ivan Getting a conçu le concept du GPS pour le département de la Défense américain, tandis que Robert Easton a développé le système de satellites Timation, posant les bases techniques du réseau."),
        Question(11177, "En quelle année le GPS a-t-il été inventé?", listOf("1973", "1969", "1977", "1981"), 0, "Technologie", Difficulty.HARD, explanation = "Le système GPS a été développé par le département de la Défense américain, et le premier satellite expérimental a été lancé en 1978, mais le projet a officiellement débuté en 1973."),
        Question(11178, "Qui a inventé la batterie au lithium?", listOf("John Goodenough", "Stanley Whittingham", "Akira Yoshino", "Nikola Tesla"), 0, "Technologie", Difficulty.HARD, explanation = "John Goodenough a inventé la batterie lithium-ion dans les années 1980, révolutionnant le stockage d'énergie portable."),
        Question(11179, "En quelle année la batterie au lithium a-t-elle été inventée?", listOf("1991", "1987", "1995", "1999"), 0, "Technologie", Difficulty.HARD, explanation = "La batterie lithium-ion a été commercialisée pour la première fois par Sony en 1991, marquant une révolution dans le stockage d'énergie portable."),
        Question(11180, "Qui a inventé le capteur de puissance?", listOf("Image Sensor Foundation", "Nikola Tesla", "Thomas Edison", "Alexander Graham Bell"), 0, "Technologie", Difficulty.EXPERT, explanation = "L'Image Sensor Foundation est un consortium industriel qui a standardisé le capteur de puissance, notamment dans le domaine des appareils photo numériques."),
        Question(11181, "En quelle année le capteur CMOS a-t-il été inventé?", listOf("1993", "1989", "1997", "2001"), 0, "Technologie", Difficulty.EXPERT, explanation = "Le capteur CMOS a été inventé en 1993 par Eric Fossum au Jet Propulsion Laboratory de la NASA. Cette technologie a révolutionné l'imagerie numérique en offrant une consommation d'énergie plus faible que les capteurs CCD."),
        Question(11182, "Quel est le premier satellite artificiel lancé dans l'espace?", listOf("Spoutnik 1", "Explorer 1", "Spoutnik 2", "Youri Gagarine"), 0, "Technologie", Difficulty.MEDIUM, explanation = "Spoutnik 1, lancé par l'Union soviétique le 4 octobre 1957, fut le premier satellite artificiel à orbiter autour de la Terre."),
        Question(11183, "En quelle année le premier satellite a-t-il été lancé?", listOf("1957", "1955", "1959", "1961"), 0, "Technologie", Difficulty.MEDIUM, explanation = "Le premier satellite artificiel, Spoutnik 1, a été lancé par l'Union soviétique le 4 octobre 1957, marquant le début de l'ère spatiale."),
        Question(11184, "Qui a été le premier homme dans l'espace?", listOf("Youri Gagarine", "Alan Shepard", "John Glenn", "Buzz Aldrin"), 0, "Technologie", Difficulty.EASY, explanation = "Le cosmonaute soviétique Youri Gagarine a effectué le premier vol spatial habité le 12 avril 1961 à bord de Vostok 1."),
        Question(11185, "En quelle année le premier vol humain spatial a-t-il eu lieu?", listOf("1961", "1959", "1963", "1965"), 0, "Technologie", Difficulty.MEDIUM, explanation = "Le premier vol spatial habité a été réalisé par le cosmonaute soviétique Youri Gagarine le 12 avril 1961, à bord du vaisseau Vostok 1."),
        Question(11186, "Qui a été le premier homme sur la Lune?", listOf("Neil Armstrong", "Buzz Aldrin", "Michael Collins", "Alan Bean"), 0, "Technologie", Difficulty.EASY, explanation = "Neil Armstrong a été le premier humain à marcher sur la Lune le 20 juillet 1969, lors de la mission Apollo 11 de la NASA."),
        Question(11187, "En quelle année l'homme a-t-il marché sur la Lune pour la première fois?", listOf("1969", "1967", "1971", "1973"), 0, "Technologie", Difficulty.EASY, explanation = "La mission Apollo 11 de la NASA a permis aux astronautes Neil Armstrong et Buzz Aldrin de poser le pied sur la Lune le 20 juillet 1969."),
        Question(11188, "Quel était le nom du premier télescope spatial?", listOf("Hubble", "Spitzer", "Kepler", "TESS"), 0, "Technologie", Difficulty.MEDIUM, explanation = "Le télescope spatial Hubble, lancé en 1990, est souvent considéré comme le premier grand observatoire spatial, bien que d'autres télescopes plus petits l'aient précédé."),
        Question(11189, "En quelle année le télescope Hubble a-t-il été lancé?", listOf("1990", "1988", "1992", "1994"), 0, "Technologie", Difficulty.MEDIUM, explanation = "Le télescope spatial Hubble a été mis en orbite le 24 avril 1990 par la navette spatiale Discovery. Il a révolutionné l'astronomie en fournissant des images d'une clarté inédite depuis l'espace."),
        Question(11190, "Quel programme spatial a envoyé des hommes sur la Lune?", listOf("Apollo", "Gemini", "Mercury", "Skylab"), 0, "Technologie", Difficulty.EASY, explanation = "Le programme Apollo de la NASA a réalisé six alunissages habités entre 1969 et 1972, Apollo 11 étant la première mission à poser des hommes sur la Lune."),
        Question(11191, "En quelle année la Station spatiale internationale a-t-elle été lancée?", listOf("1998", "1996", "2000", "2002"), 0, "Technologie", Difficulty.MEDIUM, explanation = "Le premier module de la Station spatiale internationale, Zarya, a été lancé en 1998, marquant le début de la construction en orbite de ce laboratoire international."),
        Question(11192, "Quel est le plus grand observatoire astronomique du monde?", listOf("Mauna Kea", "Paranal", "La Silla", "Greenwich"), 0, "Technologie", Difficulty.HARD, explanation = "Le Mauna Kea, à Hawaï, abrite plusieurs télescopes majeurs à son sommet, à plus de 4 200 mètres d'altitude, offrant des conditions d'observation optimales grâce à la faible pollution lumineuse et à l'atmosphère stable."),
        Question(11193, "En quelle année Perseverance a-t-il été lancé vers Mars?", listOf("2020", "2018", "2022", "2024"), 0, "Technologie", Difficulty.MEDIUM, explanation = "Le rover Perseverance a été lancé le 30 juillet 2020 dans le cadre de la mission Mars 2020 de la NASA."),
        Question(11194, "Qui a créé le premier rover lunaire?", listOf("NASA", "Agence spatiale russe", "Agence spatiale chinoise", "ESA"), 0, "Technologie", Difficulty.HARD, explanation = "Le premier rover lunaire, le Lunokhod 1, a été créé par l'Union soviétique en 1970, mais la NASA a développé le rover lunaire habité utilisé lors des missions Apollo 15, 16 et 17."),
        Question(11195, "En quelle année le rover Curiosity a-t-il débarqué sur Mars?", listOf("2012", "2010", "2014", "2016"), 0, "Technologie", Difficulty.MEDIUM, explanation = "Le rover Curiosity a atterri sur Mars le 6 août 2012 dans le cadre de la mission Mars Science Laboratory de la NASA."),
        Question(11196, "Quel est le plus grand télescope spatial actuel?", listOf("James Webb", "Hubble", "Spitzer", "Kepler"), 0, "Technologie", Difficulty.HARD, explanation = "Le télescope spatial James Webb, lancé en 2021, est le plus grand jamais déployé dans l'espace, avec un miroir principal de 6,5 mètres de diamètre."),
        Question(11197, "En quelle année le télescope James Webb a-t-il été lancé?", listOf("2021", "2019", "2023", "2025"), 0, "Technologie", Difficulty.MEDIUM, explanation = "Le télescope spatial James Webb a été lancé le 25 décembre 2021 depuis Kourou, en Guyane française, après de nombreux reports. Il succède au télescope Hubble pour observer l'univers en infrarouge."),
        Question(11198, "Quel est le plus proche exoplanète découverte?", listOf("Proxima Centauri b", "Trappist-1e", "WASP-12b", "HD 209458b"), 0, "Technologie", Difficulty.HARD, explanation = "Proxima Centauri b orbite autour de Proxima du Centaure, l'étoile la plus proche du Soleil, située à environ 4,2 années-lumière."),
        Question(11199, "En quelle année Kepler a-t-il découvert les premières exoplanètes?", listOf("2009", "2007", "2011", "2013"), 0, "Technologie", Difficulty.HARD, explanation = "La mission Kepler de la NASA a été lancée en mars 2009, et ses premières découvertes d'exoplanètes ont été annoncées la même année."),
        Question(11200, "Quel est le plus grand trou noir connu?", listOf("TON 618", "Phoenix A", "IC 1101", "Holmberg 15A"), 0, "Technologie", Difficulty.EXPERT, explanation = "TON 618 est un quasar extrêmement lumineux abritant un trou noir supermassif estimé à 66 milliards de masses solaires, ce qui en fait le plus massif jamais observé."),
        Question(11201, "Combien de transistors le processeur Apple M1 contient-il?", listOf("16 milliards", "10 milliards", "20 milliards", "25 milliards"), 0, "Technologie", Difficulty.HARD, explanation = "L'Apple M1, premier processeur conçu par Apple pour ses Mac, intègre 16 milliards de transistors sur une puce de 5 nanomètres, une densité élevée qui permet des performances et une efficacité énergétique remarquables."),
        Question(11202, "Quel est le processeur le plus puissant actuellement?", listOf("NVIDIA H100", "Apple M3 Max", "AMD EPYC", "Intel Xeon"), 0, "Technologie", Difficulty.HARD, explanation = "Le NVIDIA H100 est une unité de traitement graphique (GPU) conçue pour l'intelligence artificielle et le calcul haute performance, surpassant les processeurs classiques dans ces tâches spécifiques."),
        Question(11203, "En quelle année le processeur Apple Silicon a-t-il été lancé?", listOf("2020", "2018", "2022", "2024"), 0, "Technologie", Difficulty.MEDIUM, explanation = "Apple a annoncé le passage des processeurs Intel à ses propres puces Apple Silicon en juin 2020, avec le lancement du MacBook Air, MacBook Pro 13 pouces et Mac mini équipés de la puce M1 en novembre 2020."),
        Question(11204, "Quel est le GPU le plus puissant actuellement?", listOf("NVIDIA RTX 6000 Ada", "RTX 4090", "AMD MI300X", "Intel Arc"), 0, "Technologie", Difficulty.HARD, explanation = "La RTX 6000 Ada est le GPU le plus puissant de NVIDIA, conçu pour les stations de travail professionnelles avec 48 Go de VRAM et une architecture Ada Lovelace."),
        Question(11205, "En quelle année RTX 4090 a-t-il été lancé?", listOf("2022", "2020", "2024", "2025"), 0, "Technologie", Difficulty.HARD, explanation = "La RTX 4090 a été lancée en octobre 2022 par Nvidia, dans le cadre de la série GeForce RTX 40 basée sur l'architecture Ada Lovelace."),
        Question(11206, "Quel est le système de refroidissement le plus efficace?", listOf("Refroidissement liquide", "Refroidissement air", "Refroidissement phase", "Thermoélectrique"), 0, "Technologie", Difficulty.HARD, explanation = "Le refroidissement liquide est plus efficace que l'air car l'eau a une capacité thermique massique plus élevée, permettant d'évacuer davantage de chaleur des composants électroniques."),
        Question(11207, "En quelle année AMD Ryzen a-t-il été lancé?", listOf("2017", "2015", "2019", "2021"), 0, "Technologie", Difficulty.HARD, explanation = "La première génération de processeurs AMD Ryzen, basée sur l'architecture Zen, a été commercialisée en mars 2017, marquant le retour d'AMD sur le marché haut de gamme face à Intel."),
        Question(11208, "Quel est le disque dur le plus rapide actuellement?", listOf("SSD NVMe", "SSD SATA", "HDD Mécanique", "Mémoire Flash"), 0, "Technologie", Difficulty.HARD, explanation = "Les SSD NVMe utilisent l'interface PCI Express, offrant des vitesses de lecture/écriture bien supérieures aux SSD SATA ou aux disques durs mécaniques, ce qui en fait le type de stockage le plus rapide actuellement."),
        Question(11209, "En quelle année Intel Core i7 a-t-il été lancé?", listOf("2008", "2006", "2010", "2012"), 0, "Technologie", Difficulty.HARD, explanation = "Le premier processeur Intel Core i7, basé sur l'architecture Nehalem, a été officiellement lancé en novembre 2008."),
        Question(11210, "Quel est le plus gros superordinateur du monde?", listOf("Frontier", "Fugaku", "Sunway", "Perlmutter"), 0, "Technologie", Difficulty.HARD, explanation = "Frontier, installé au Oak Ridge National Laboratory aux États-Unis, a dépassé le japonais Fugaku en juin 2022 pour devenir le superordinateur le plus puissant, avec une performance de plus d'un exaflop."),
        Question(11211, "Qui a créé Instagram?", listOf("Kevin Systrom et Mike Krieger", "Mark Zuckerberg", "Jack Dorsey", "Evan Spiegel"), 0, "Technologie", Difficulty.EASY, explanation = "Kevin Systrom a cofondé Instagram avec Mike Krieger en 2010, initialement lancé sous le nom de Burbn avant de se recentrer sur le partage de photos."),
        Question(11212, "En quelle année Instagram a-t-il été fondé?", listOf("2010", "2008", "2012", "2014"), 0, "Technologie", Difficulty.MEDIUM, explanation = "Instagram a été fondé en 2010 par Kevin Systrom et Mike Krieger, initialement sous le nom de Burbn avant d'être renommé et lancé en octobre de la même année."),
        Question(11213, "Qui a créé Twitter?", listOf("Jack Dorsey, Noah Glass, Evan Williams, Christopher Stone", "Mark Zuckerberg", "Kevin Systrom", "Evan Spiegel"), 0, "Technologie", Difficulty.MEDIUM, explanation = "Jack Dorsey, Noah Glass, Evan Williams et Christopher Stone ont cofondé Twitter en 2006, avec Dorsey souvent considéré comme l'inventeur principal du concept de microblogging."),
