        Question(11290, "En quelle année AES a-t-il été adopté comme standard?", listOf("2001", "1999", "2003", "2005"), 0, "Technologie", Difficulty.HARD, explanation = "L'AES (Advanced Encryption Standard) a été adopté comme standard fédéral de chiffrement par le National Institute of Standards and Technology (NIST) en 2001, remplaçant le DES."),
