        Question(11292, "En quelle année RSA a-t-il été créé?", listOf("1977", "1975", "1979", "1981"), 0, "Technologie", Difficulty.HARD, explanation = "RSA a été inventé en 1977 par Ron Rivest, Adi Shamir et Leonard Adleman au MIT, d'où son nom issu de leurs initiales."),
        Question(11293, "Quel est le protocole HTTPS?", listOf("HTTP Secure avec SSL/TLS", "HTTP Secure Protocol", "HyperText Protocol Secure", "HTTP Super Secure"), 0, "Technologie", Difficulty.MEDIUM, explanation = "HTTPS est la version sécurisée du protocole HTTP, utilisant les protocoles SSL/TLS pour chiffrer les échanges entre le navigateur et le serveur web."),
