        Question(11296, "En quelle année SSL a-t-il été créé?", listOf("1994", "1992", "1996", "1998"), 0, "Technologie", Difficulty.HARD, explanation = "Netscape a développé le protocole SSL (Secure Sockets Layer) en 1994 pour sécuriser les transactions en ligne, notamment avec son navigateur Navigator."),
        Question(11297, "Quel est le type de code malveillant qui se propage via email?", listOf("Virus", "Worm", "Trojan", "Rootkit"), 0, "Technologie", Difficulty.MEDIUM, explanation = "Les virus informatiques sont souvent conçus pour se propager via des pièces jointes ou des liens malveillants dans les emails, infectant ainsi d'autres systèmes."),
        Question(11298, "En quelle année l'ILOVEYOU a-t-il frappé le monde?", listOf("2000", "1998", "2002", "2004"), 0, "Technologie", Difficulty.HARD, explanation = "Le ver ILOVEYOU, l'un des premiers virus informatiques massifs, s'est propagé en mai 2000 via des emails, infectant des millions d'ordinateurs dans le monde."),
        Question(11299, "Quel est le protocole de communication le plus ancien?", listOf("SMTP", "HTTP", "FTP", "Telnet"), 0, "Technologie", Difficulty.HARD, explanation = "SMTP (Simple Mail Transfer Protocol) a été développé en 1982, ce qui en fait l'un des plus anciens protocoles encore utilisés sur Internet, conçu pour l'envoi de courriers électroniques."),
