        Question(11302, "En quelle année Archie a-t-il été créé?", listOf("1990", "1988", "1992", "1994"), 0, "Technologie", Difficulty.HARD, explanation = "Archie, considéré comme le premier moteur de recherche internet, a été créé en 1990 par Alan Emtage, un étudiant de l'Université McGill."),
        Question(11303, "Quel est le créateur d'Archie?", listOf("Alan Emtage", "Mark Zuckerberg", "Jack Dorsey", "Steve Jobs"), 0, "Technologie", Difficulty.EXPERT, explanation = "Alan Emtage a créé Archie en 1990, considéré comme le premier moteur de recherche sur Internet, permettant d'indexer des fichiers FTP."),
        Question(11304, "En quelle année Veronica a-t-il été créé?", listOf("1992", "1990", "1994", "1996"), 0, "Technologie", Difficulty.EXPERT, explanation = "Veronica, un des premiers moteurs de recherche sur le web, a été créé en 1992 par des étudiants de l’Université du Nevada."),
        Question(11305, "Quel est le créateur de Veronica?", listOf("Université du Nevada", "Université d'Oxford", "Université de Stanford", "MIT"), 0, "Technologie", Difficulty.EXPERT, explanation = "Veronica, l'un des premiers moteurs de recherche sur Internet, a été créée par des chercheurs de l'Université du Nevada en 1992."),
