        Question(11307, "Qui a créé Yahoo?", listOf("Jerry Yang et David Filo", "Mark Zuckerberg", "Jack Dorsey", "Steve Jobs"), 0, "Technologie", Difficulty.HARD, explanation = "Jerry Yang et David Filo ont fondé Yahoo en 1994 alors qu'ils étaient étudiants à l'Université Stanford, initialement comme un annuaire de sites web appelé \"Jerry and David's Guide to the World Wide Web\"."),
