        Question(11369, "En quelle année Dart a-t-il été créé?", listOf("2011", "2009", "2013", "2015"), 0, "Technologie", Difficulty.HARD, explanation = "Dart a été dévoilé par Google en 2011 comme une alternative à JavaScript pour le développement web. Il a été conçu par Lars Bak et Kasper Lund."),
        Question(11370, "En quelle année R a-t-il été créé?", listOf("1993", "1991", "1995", "1997"), 0, "Technologie", Difficulty.HARD, explanation = "R a été créé en 1993 par Ross Ihaka et Robert Gentleman à l'Université d'Auckland, en Nouvelle-Zélande, comme un langage de programmation statistique."),
        Question(11371, "En quelle année MATLAB a-t-il été créé?", listOf("1984", "1982", "1986", "1988"), 0, "Technologie", Difficulty.HARD, explanation = "MATLAB a été créé en 1984 par Cleve Moler, un mathématicien américain, pour offrir un accès simplifié aux bibliothèques de calcul numérique."),
        Question(11372, "En quelle année Lua a-t-il été créé?", listOf("1993", "1991", "1995", "1997"), 0, "Technologie", Difficulty.HARD, explanation = "Lua a été créé en 1993 par un groupe de chercheurs brésiliens de l'Université pontificale catholique de Rio de Janeiro pour offrir un langage de script léger et extensible."),
        Question(11373, "En quelle année Groovy a-t-il été créé?", listOf("2003", "2001", "2005", "2007"), 0, "Technologie", Difficulty.HARD, explanation = "Groovy a été créé par James Strachan en 2003 comme un langage de script dynamique pour la plateforme Java, visant à offrir une syntaxe plus concise."),
        Question(11374, "En quelle année Scala a-t-il été créé?", listOf("2004", "2002", "2006", "2008"), 0, "Technologie", Difficulty.HARD, explanation = "Scala a été conçu par Martin Odersky et présenté pour la première fois en 2004, combinant programmation fonctionnelle et orientée objet pour la machine virtuelle Java."),
        Question(11375, "En quelle année Clojure a-t-il été créé?", listOf("2007", "2005", "2009", "2011"), 0, "Technologie", Difficulty.HARD, explanation = "Clojure a été créé par Rich Hickey en 2007 comme un dialecte moderne de Lisp fonctionnant sur la machine virtuelle Java (JVM)."),
        Question(11376, "En quelle année Elixir a-t-il été créé?", listOf("2011", "2009", "2013", "2015"), 0, "Technologie", Difficulty.HARD, explanation = "Elixir a été créé en 2011 par le développeur José Valim, initialement comme un langage de programmation fonctionnel conçu pour la concurrence et la tolérance aux pannes, s'appuyant sur la machine virtuelle Erlang."),
        Question(11377, "En quelle année Haskell a-t-il été créé?", listOf("1990", "1988", "1992", "1994"), 0, "Technologie", Difficulty.HARD, explanation = "Haskell a été créé en 1990 par un comité de chercheurs, dont Simon Peyton Jones, pour standardiser les langages fonctionnels paresseux existants."),
        Question(11378, "En quelle année OCaml a-t-il été créé?", listOf("1996", "1994", "1998", "2000"), 0, "Technologie", Difficulty.HARD, explanation = "OCaml a été créé en 1996 par l'INRIA, issu de la fusion du langage Caml Special Light avec des fonctionnalités orientées objet."),
        Question(11379, "En quelle année Scheme a-t-il été créé?", listOf("1975", "1973", "1977", "1979"), 0, "Technologie", Difficulty.HARD, explanation = "Scheme a été créé en 1975 par Guy L. Steele Jr. et Gerald Jay Sussman au MIT, comme un dialecte minimaliste du langage Lisp."),
        Question(11380, "Quel est le protocole de transfert de fichiers le plus ancien?", listOf("FTP", "SFTP", "SCP", "RSYNC"), 0, "Technologie", Difficulty.HARD, explanation = "FTP (File Transfer Protocol) a été développé en 1971, bien avant HTTP, ce qui en fait le plus ancien protocole standard de transfert de fichiers sur Internet."),
        Question(11381, "En quelle année FTP a-t-il été créé?", listOf("1971", "1969", "1973", "1975"), 0, "Technologie", Difficulty.HARD, explanation = "Le protocole FTP (File Transfer Protocol) a été développé en 1971 par Abhay Bhushan dans le cadre du projet ARPANET, l'ancêtre d'Internet."),
        Question(11382, "Quel est le protocole de shell sécurisé?", listOf("SSH", "Telnet", "Rsh", "Rlogin"), 0, "Technologie", Difficulty.MEDIUM, explanation = "SSH, pour Secure Shell, est un protocole réseau qui permet de se connecter à distance à un serveur de manière chiffrée, offrant une alternative sécurisée à des protocoles non cryptés comme Telnet."),
        Question(11383, "En quelle année SSH a-t-il été créé?", listOf("1995", "1993", "1997", "1999"), 0, "Technologie", Difficulty.HARD, explanation = "SSH a été développé en 1995 par Tatu Ylönen à l'université d'Helsinki pour remplacer les protocoles non sécurisés comme Telnet."),
        Question(11384, "Qui a créé SSH?", listOf("Tatu Ylönen", "Mark Zuckerberg", "Jack Dorsey", "Steve Jobs"), 0, "Technologie", Difficulty.HARD, explanation = "Tatu Ylönen a développé SSH en 1995 pour remplacer les protocoles non sécurisés comme Telnet, après une attaque par sniffing de mots de passe sur son réseau universitaire en Finlande."),
        Question(11385, "Quel est le protocole de messagerie le plus ancien?", listOf("SMTP", "POP3", "IMAP", "MAPI"), 0, "Technologie", Difficulty.HARD, explanation = "SMTP (Simple Mail Transfer Protocol) a été défini en 1982 dans la RFC 821, ce qui en fait le plus ancien protocole de messagerie encore utilisé aujourd'hui."),
        Question(11386, "En quelle année POP3 a-t-il été créé?", listOf("1988", "1986", "1990", "1992"), 0, "Technologie", Difficulty.HARD, explanation = "Le protocole POP3 (Post Office Protocol version 3) a été développé en 1988 pour permettre la récupération de courriels depuis un serveur distant."),
        Question(11387, "En quelle année IMAP a-t-il été créé?", listOf("1986", "1984", "1988", "1990"), 0, "Technologie", Difficulty.HARD, explanation = "IMAP a été créé en 1986 par Mark Crispin comme alternative à POP, permettant une gestion plus flexible des emails directement sur le serveur."),
        Question(11388, "Quel est le protocole DNS?", listOf("Domain Name System", "Dynamic Network System", "Data Network Service", "Digital Name System"), 0, "Technologie", Difficulty.MEDIUM, explanation = "Le DNS, pour Domain Name System, est le protocole qui traduit les noms de domaine lisibles par les humains en adresses IP numériques, permettant ainsi d'accéder aux sites web."),
        Question(11389, "En quelle année DNS a-t-il été créé?", listOf("1983", "1981", "1985", "1987"), 0, "Technologie", Difficulty.HARD, explanation = "Le système DNS (Domain Name System) a été inventé en 1983 par Paul Mockapetris pour remplacer le fichier hosts.txt, permettant de traduire les noms de domaine en adresses IP."),
        Question(11390, "Qui a créé DNS?", listOf("Paul Mockapetris", "Mark Zuckerberg", "Jack Dorsey", "Steve Jobs"), 0, "Technologie", Difficulty.HARD, explanation = "Paul Mockapetris a conçu le Domain Name System (DNS) en 1983, alors qu'il travaillait à l'Université de Californie du Sud, pour remplacer le fichier hosts.txt centralisé."),
        Question(11391, "Quel est le protocole DHCP?", listOf("Dynamic Host Configuration Protocol", "Dynamic Hardware Configuration Protocol", "Data Host Configuration Protocol", "Digital Host Configuration Protocol"), 0, "Technologie", Difficulty.HARD, explanation = "Le DHCP (Dynamic Host Configuration Protocol) attribue automatiquement des adresses IP et autres paramètres réseau aux appareils, évitant une configuration manuelle."),
        Question(11392, "En quelle année DHCP a-t-il été créé?", listOf("1993", "1991", "1995", "1997"), 0, "Technologie", Difficulty.HARD, explanation = "DHCP a été créé en 1993 en tant que successeur du protocole BOOTP, permettant l'attribution automatique d'adresses IP sur les réseaux."),
        Question(11393, "Quel est le protocole ARP?", listOf("Address Resolution Protocol", "Advanced Resolution Protocol", "Application Resolution Protocol", "Adapter Resolution Protocol"), 0, "Technologie", Difficulty.HARD, explanation = "ARP, pour Address Resolution Protocol, est un protocole réseau qui associe une adresse IP à une adresse MAC sur un réseau local, permettant ainsi la communication entre machines."),
        Question(11394, "En quelle année ARP a-t-il été créé?", listOf("1982", "1980", "1984", "1986"), 0, "Technologie", Difficulty.HARD, explanation = "ARPANET a adopté le protocole ARP (Address Resolution Protocol) en 1982, permettant de mapper les adresses IP aux adresses physiques des machines sur le réseau."),
        Question(11395, "Quel est le protocole ICMP?", listOf("Internet Control Message Protocol", "Internet Communication Message Protocol", "Internet Control Management Protocol", "Internet Computer Message Protocol"), 0, "Technologie", Difficulty.HARD, explanation = "ICMP est un protocole de la couche réseau utilisé pour transmettre des messages d'erreur et des informations opérationnelles, comme dans la commande ping."),
        Question(11396, "En quelle année ICMP a-t-il été créé?", listOf("1981", "1979", "1983", "1985"), 0, "Technologie", Difficulty.HARD, explanation = "Le protocole ICMP (Internet Control Message Protocol) a été défini pour la première fois dans la RFC 792 en septembre 1981, dans le cadre du développement des protocoles TCP/IP."),
        Question(11397, "Quel est le protocole UDP?", listOf("User Datagram Protocol", "Universal Data Protocol", "Unified Data Protocol", "Unique Data Protocol"), 0, "Technologie", Difficulty.HARD, explanation = "UDP signifie User Datagram Protocol, un protocole de communication qui envoie des données sans établir de connexion préalable, privilégiant la vitesse sur la fiabilité."),
        Question(11398, "En quelle année UDP a-t-il été créé?", listOf("1980", "1978", "1982", "1984"), 0, "Technologie", Difficulty.HARD, explanation = "UDP (User Datagram Protocol) a été conçu par David P. Reed en 1980 et standardisé dans la RFC 768, afin de fournir un protocole de transport sans connexion pour Internet."),
        Question(11399, "Quel est le protocole TCP?", listOf("Transmission Control Protocol", "Transfer Control Protocol", "Transport Control Protocol", "Trusted Control Protocol"), 0, "Technologie", Difficulty.MEDIUM, explanation = "TCP signifie Transmission Control Protocol et est un protocole fondamental d'Internet, garantissant une transmission fiable et ordonnée des données entre les appareils."),
        Question(11400, "En quelle année TCP a-t-il été créé?", listOf("1974", "1972", "1976", "1978"), 0, "Technologie", Difficulty.HARD, explanation = "TCP a été créé en 1974 par Vint Cerf et Bob Kahn, posant les bases du protocole qui deviendra plus tard TCP/IP, essentiel à Internet."),
        Question(11401, "Quel était le nom du premier téléphone intelligent?", listOf("Simon", "iPhone", "Blackberry", "Windows Mobile"), 0, "Technologie", Difficulty.HARD, explanation = "Le IBM Simon, lancé en 1994, est considéré comme le premier smartphone car il combinait téléphone mobile et fonctions d'assistant personnel tactile."),
        Question(11402, "En quelle année Simon a-t-il été lancé?", listOf("1994", "1992", "1996", "1998"), 0, "Technologie", Difficulty.HARD, explanation = "Simon est un assistant vocal développé par Bell Labs, lancé en 1994, considéré comme le premier smartphone de l'histoire."),
