        Question(11422, "Qui a créé Oppo?", listOf("Chen Mingyong", "Lei Jun", "Jack Ma", "Pony Ma"), 0, "Technologie", Difficulty.HARD, explanation = "Chen Mingyong a fondé Oppo en 2001, initialement comme une marque de lecteurs MP3, avant de se lancer dans les smartphones."),
