        Question(11429, "En quelle année Huawei a-t-il été créé?", listOf("1987", "1985", "1989", "1991"), 0, "Technologie", Difficulty.HARD, explanation = "Huawei a été fondé en 1987 à Shenzhen, en Chine, par Ren Zhengfei, un ancien ingénieur de l'Armée populaire de libération."),
        Question(11430, "Qui a créé Huawei?", listOf("Ren Zhengfei", "Lei Jun", "Jack Ma", "Pony Ma"), 0, "Technologie", Difficulty.HARD, explanation = "Ren Zhengfei, un ancien ingénieur de l'Armée populaire de libération, a fondé Huawei en 1987 à Shenzhen, en Chine."),
        Question(11431, "Quel est le plus ancien social media?", listOf("The WELL", "Usenet", "BBS", "Bulletin Board System"), 0, "Technologie", Difficulty.HARD, explanation = "Lancé en 1985, The WELL est un système de conférence en ligne qui est considéré comme l'un des premiers réseaux sociaux, avant l'avènement d'Internet grand public."),
        Question(11432, "En quelle année The WELL a-t-il été créé?", listOf("1985", "1983", "1987", "1989"), 0, "Technologie", Difficulty.HARD, explanation = "The WELL (Whole Earth 'Lectronic Link) a été fondé en 1985 par Stewart Brand et Larry Brilliant, devenant l'un des premiers forums en ligne influents."),
