        Question(11441, "En quelle année Prodigy a-t-il été créé?", listOf("1984", "1982", "1986", "1988"), 0, "Technologie", Difficulty.HARD, explanation = "Prodigy, l'un des premiers fournisseurs de services en ligne, a été lancé en 1984 comme un service de téléachat et d'information."),
        Question(11442, "En quelle année Minitel a-t-il été créé?", listOf("1978", "1976", "1980", "1982"), 0, "Technologie", Difficulty.HARD, explanation = "Le Minitel a été lancé en 1978 par les PTT (ancêtre de France Telecom) pour moderniser l'annuaire téléphonique français. Ce service en ligne a connu un succès massif dans les années 1980-1990 avant d'être supprimé en 2012."),
