        Question(11444, "Quel est le premier webmail?", listOf("Hotmail", "Gmail", "Yahoo Mail", "AOL Mail"), 0, "Technologie", Difficulty.HARD, explanation = "Hotmail, lancé en 1996 par Sabeer Bhatia et Jack Smith, est considéré comme le premier service de messagerie web accessible via un navigateur."),
