        Question(11446, "Qui a créé Hotmail?", listOf("Sabeer Bhatia et Jack Smith", "Mark Zuckerberg", "Jack Dorsey", "Steve Jobs"), 0, "Technologie", Difficulty.HARD, explanation = "Hotmail a été fondé en 1996 par les programmeurs Sabeer Bhatia et Jack Smith, qui ont eu l'idée d'un service de messagerie accessible via le web."),
        Question(11447, "En quelle année Gmail a-t-il été créé?", listOf("2004", "2002", "2006", "2008"), 0, "Technologie", Difficulty.MEDIUM, explanation = "Gmail a été lancé par Google le 1er avril 2004, initialement en version bêta avec une capacité de stockage de 1 Go, ce qui était révolutionnaire à l'époque."),
        Question(11448, "Qui a créé Gmail?", listOf("Google", "Microsoft", "Yahoo", "Apple"), 0, "Technologie", Difficulty.MEDIUM, explanation = "Gmail a été développé par Paul Buchheit, un ingénieur de Google, et lancé en 2004."),
        Question(11449, "En quelle année Yahoo Mail a-t-il été créé?", listOf("1997", "1995", "1999", "2001"), 0, "Technologie", Difficulty.HARD, explanation = "Yahoo Mail a été lancé en 1997, devenant l'un des premiers services de messagerie web gratuits et populaires, concurrençant Hotmail lancé l'année précédente."),
        Question(11450, "En quelle année Outlook a-t-il été créé?", listOf("1997", "1995", "1999", "2001"), 0, "Technologie", Difficulty.HARD, explanation = "Outlook a été lancé en 1997 dans le cadre de la suite Microsoft Office 97, succédant à Microsoft Mail et Schedule+."),
        Question(11451, "En quelle année le protocole SSL a-t-il été créé?", listOf("1994", "1992", "1996", "1998"), 0, "Technologie", Difficulty.HARD, explanation = "Le protocole SSL (Secure Sockets Layer) a été développé par Netscape en 1994 pour sécuriser les communications sur Internet, notamment pour les transactions en ligne."),
        Question(11452, "En quelle année HTTPS a-t-il été standardisé?", listOf("1994", "1992", "1996", "1998"), 0, "Technologie", Difficulty.HARD, explanation = "HTTPS a été standardisé en 1994 par Netscape Communications pour sécuriser les transactions web, intégrant le protocole SSL dans les communications HTTP."),
        Question(11453, "Quel est le premier navigateur graphique?", listOf("Mosaic", "Netscape", "Internet Explorer", "Opera"), 0, "Technologie", Difficulty.HARD, explanation = "Développé en 1993 au NCSA, Mosaic a popularisé l'affichage d'images et de texte sur le web, devenant le premier navigateur graphique grand public."),
        Question(11454, "En quelle année Mosaic a-t-il été créé?", listOf("1993", "1991", "1995", "1997"), 0, "Technologie", Difficulty.HARD, explanation = "Mosaic, développé au National Center for Supercomputing Applications, a été lancé en 1993 et est considéré comme le premier navigateur web à populariser l'interface graphique pour le grand public."),
        Question(11455, "Qui a créé Mosaic?", listOf("Marc Andreessen et al.", "Mark Zuckerberg", "Jack Dorsey", "Steve Jobs"), 0, "Technologie", Difficulty.HARD, explanation = "Marc Andreessen a codirigé le développement de Mosaic, le premier navigateur web grand public, à l'Université de l'Illinois en 1993."),
        Question(11456, "En quelle année Netscape a-t-il été créé?", listOf("1994", "1992", "1996", "1998"), 0, "Technologie", Difficulty.HARD, explanation = "Netscape Communications Corporation a été fondée en avril 1994 par Marc Andreessen et Jim Clark, lançant le navigateur Netscape Navigator qui a popularisé le web."),
        Question(11457, "En quelle année Internet Explorer a-t-il été lancé?", listOf("1995", "1993", "1997", "1999"), 0, "Technologie", Difficulty.HARD, explanation = "Internet Explorer a été lancé par Microsoft en 1995 dans le cadre du complément Internet pour Windows 95."),
        Question(11458, "En quelle année Opera a-t-il été créé?", listOf("1995", "1993", "1997", "1999"), 0, "Technologie", Difficulty.HARD, explanation = "Opera a été fondé en 1995 par une équipe de chercheurs norvégiens, initialement comme un projet de recherche universitaire. Le navigateur a été lancé publiquement en 1996."),
        Question(11459, "En quelle année Firefox a-t-il été créé?", listOf("2004", "2002", "2006", "2008"), 0, "Technologie", Difficulty.MEDIUM, explanation = "Firefox, initialement nommé Phoenix, a été lancé en 2004 par la Fondation Mozilla comme successeur du navigateur Mozilla Suite."),
        Question(11460, "En quelle année Chrome a-t-il été créé?", listOf("2008", "2006", "2010", "2012"), 0, "Technologie", Difficulty.MEDIUM, explanation = "Google a lancé le navigateur Chrome en septembre 2008, principalement pour concurrencer Internet Explorer et Firefox."),
        Question(11461, "En quelle année Safari a-t-il été créé?", listOf("2003", "2001", "2005", "2007"), 0, "Technologie", Difficulty.MEDIUM, explanation = "Safari a été lancé par Apple en 2003 comme navigateur par défaut pour Mac OS X Jaguar. Il a succédé à Internet Explorer pour Mac."),
        Question(11462, "En quelle année Edge a-t-il été créé?", listOf("2015", "2013", "2017", "2019"), 0, "Technologie", Difficulty.MEDIUM, explanation = "Microsoft Edge a été lancé en 2015 en tant que successeur d'Internet Explorer, avec Windows 10."),
        Question(11463, "Quel est le premier langage de balisage?", listOf("SGML", "HTML", "XML", "XHTML"), 0, "Technologie", Difficulty.HARD, explanation = "SGML (Standard Generalized Markup Language) a été développé dans les années 1980 et normalisé en 1986, servant de métalangage pour définir d'autres langages de balisage, dont HTML et XML."),
        Question(11464, "En quelle année SGML a-t-il été créé?", listOf("1986", "1984", "1988", "1990"), 0, "Technologie", Difficulty.HARD, explanation = "SGML (Standard Generalized Markup Language) a été normalisé en 1986 par l'Organisation internationale de normalisation (ISO). Ce langage a servi de base au développement du HTML et du XML."),
        Question(11465, "En quelle année HTML a-t-il été créé?", listOf("1993", "1991", "1995", "1997"), 0, "Technologie", Difficulty.HARD, explanation = "HTML a été créé en 1993 par Tim Berners-Lee, qui a publié la première spécification du langage de balisage pour le World Wide Web."),
        Question(11466, "En quelle année XML a-t-il été créé?", listOf("1998", "1996", "2000", "2002"), 0, "Technologie", Difficulty.HARD, explanation = "XML a été publié comme recommandation par le W3C en février 1998, conçu pour structurer et échanger des données de manière flexible sur le web."),
        Question(11467, "En quelle année CSS a-t-il été créé?", listOf("1996", "1994", "1998", "2000"), 0, "Technologie", Difficulty.HARD, explanation = "CSS a été proposé par Håkon Wium Lie en octobre 1994, mais la première recommandation officielle du W3C, CSS1, a été publiée en décembre 1996."),
        Question(11468, "Qui a créé CSS?", listOf("Håkon Wium Lie", "Tim Berners-Lee", "Mark Zuckerberg", "Jack Dorsey"), 0, "Technologie", Difficulty.HARD, explanation = "Håkon Wium Lie a proposé les feuilles de style en cascade (CSS) en 1994 alors qu'il travaillait au CERN, afin de séparer le contenu HTML de la présentation visuelle des pages web."),
        Question(11469, "En quelle année SVG a-t-il été créé?", listOf("2001", "1999", "2003", "2005"), 0, "Technologie", Difficulty.HARD, explanation = "Le format SVG (Scalable Vector Graphics) a été développé par le World Wide Web Consortium (W3C) et sa première version recommandée a été publiée en 2001."),
        Question(11470, "En quelle année JSON a-t-il été créé?", listOf("2002", "2000", "2004", "2006"), 0, "Technologie", Difficulty.HARD, explanation = "JSON a été créé en 2002 par Douglas Crockford pour simplifier l'échange de données entre serveurs et applications web, en alternative plus légère à XML."),
        Question(11471, "Qui a créé JSON?", listOf("Douglas Crockford", "Tim Berners-Lee", "Mark Zuckerberg", "Jack Dorsey"), 0, "Technologie", Difficulty.HARD, explanation = "Douglas Crockford a popularisé et spécifié le format JSON au début des années 2000, en s'inspirant de la notation des objets en JavaScript. Il en a fait un standard léger d'échange de données."),
        Question(11472, "En quelle année YAML a-t-il été créé?", listOf("2001", "1999", "2003", "2005"), 0, "Technologie", Difficulty.HARD, explanation = "YAML a été créé en 2001 par Clark Evans, avec la première version publiée cette année-là. Ce format de sérialisation de données a été conçu pour être lisible par les humains."),
        Question(11473, "En quelle année Protocol Buffers a-t-il été créé?", listOf("2008", "2006", "2010", "2012"), 0, "Technologie", Difficulty.HARD, explanation = "Protocol Buffers a été créé par Google en 2008 pour remplacer XML comme format de sérialisation de données plus efficace et plus rapide."),
        Question(11474, "Qui a créé Protocol Buffers?", listOf("Google", "Facebook", "Amazon", "Microsoft"), 0, "Technologie", Difficulty.HARD, explanation = "Protocol Buffers ont été développés par Google pour remplacer XML dans la sérialisation de données structurées, offrant une solution plus rapide et plus compacte."),
        Question(11475, "En quelle année ASN.1 a-t-il été créé?", listOf("1984", "1982", "1986", "1988"), 0, "Technologie", Difficulty.HARD, explanation = "ASN.1 a été créé en 1984 par le CCITT (aujourd'hui ITU-T) pour standardiser la description de données structurées dans les télécommunications."),
        Question(11476, "En quelle année REST a-t-il été introduit?", listOf("2000", "1998", "2002", "2004"), 0, "Technologie", Difficulty.HARD, explanation = "REST a été introduit par Roy Fielding dans sa thèse de doctorat en 2000, définissant les principes architecturaux pour les services web."),
        Question(11477, "Qui a introduit REST?", listOf("Roy Thomas Fielding", "Tim Berners-Lee", "Mark Zuckerberg", "Jack Dorsey"), 0, "Technologie", Difficulty.HARD, explanation = "Roy Thomas Fielding a introduit REST dans sa thèse de doctorat en 2000, définissant les principes architecturaux du web."),
        Question(11478, "En quelle année SOAP a-t-il été créé?", listOf("1998", "1996", "2000", "2002"), 0, "Technologie", Difficulty.HARD, explanation = "SOAP (Simple Object Access Protocol) a été développé par Microsoft en 1998 comme protocole d'échange de données structurées pour les services web."),
        Question(11479, "Qui a créé SOAP?", listOf("Microsoft et al.", "Google", "Amazon", "Apple"), 0, "Technologie", Difficulty.HARD, explanation = "SOAP a été développé par Microsoft en collaboration avec d'autres entreprises, puis soumis au W3C pour standardisation."),
        Question(11480, "En quelle année OAuth a-t-il été créé?", listOf("2010", "2008", "2012", "2014"), 0, "Technologie", Difficulty.HARD, explanation = "OAuth a été créé en 2010 par une équipe de développeurs, dont Blaine Cook, pour standardiser l'autorisation sécurisée d'accès aux données sans partager de mots de passe."),
        Question(11481, "En quelle année OpenID a-t-il été créé?", listOf("2005", "2003", "2007", "2009"), 0, "Technologie", Difficulty.HARD, explanation = "OpenID a été créé en 2005 par une communauté open source pour fournir un système d'authentification décentralisé."),
        Question(11482, "En quelle année SAML a-t-il été créé?", listOf("2002", "2000", "2004", "2006"), 0, "Technologie", Difficulty.HARD, explanation = "SAML (Security Assertion Markup Language) a été développé par l'OASIS Security Services Technical Committee et sa version 1.0 a été publiée en novembre 2002."),
        Question(11483, "Quel est le plus ancien système d'exploitation en production?", listOf("UNIX", "Linux", "Windows", "macOS"), 0, "Technologie", Difficulty.HARD, explanation = "UNIX a été développé à la fin des années 1960 chez Bell Labs et est toujours utilisé aujourd'hui, ce qui en fait le plus ancien système d'exploitation encore en production."),
        Question(11484, "En quelle année UNIX a-t-il été créé?", listOf("1969", "1967", "1971", "1973"), 0, "Technologie", Difficulty.HARD, explanation = "UNIX a été créé en 1969 par Ken Thompson et Dennis Ritchie aux laboratoires Bell d'AT&T."),
        Question(11485, "Qui a créé UNIX?", listOf("Ken Thompson et Dennis Ritchie", "Mark Zuckerberg", "Steve Jobs", "Bill Gates"), 0, "Technologie", Difficulty.HARD, explanation = "Ken Thompson et Dennis Ritchie ont développé UNIX aux Bell Labs dans les années 1970, posant les bases des systèmes d'exploitation modernes."),
        Question(11486, "En quelle année Linux a-t-il été créé?", listOf("1991", "1989", "1993", "1995"), 0, "Technologie", Difficulty.MEDIUM, explanation = "Linux a été créé en 1991 par Linus Torvalds, alors étudiant à l'université d'Helsinki, comme un noyau de système d'exploitation libre."),
        Question(11487, "Qui a créé Linux?", listOf("Linus Torvalds", "Richard Stallman", "Steve Jobs", "Bill Gates"), 0, "Technologie", Difficulty.EASY, explanation = "Linus Torvalds a créé le noyau Linux en 1991 alors qu'il était étudiant à l'université d'Helsinki, en Finlande."),
        Question(11488, "En quelle année GNU a-t-il été créé?", listOf("1983", "1981", "1985", "1987"), 0, "Technologie", Difficulty.HARD, explanation = "Le projet GNU a été officiellement lancé le 27 septembre 1983 par Richard Stallman, avec pour objectif de créer un système d'exploitation libre et compatible avec Unix."),
        Question(11489, "Qui a créé GNU?", listOf("Richard Stallman", "Linus Torvalds", "Steve Jobs", "Bill Gates"), 0, "Technologie", Difficulty.HARD, explanation = "Richard Stallman a lancé le projet GNU en 1983 pour créer un système d'exploitation libre, posant les bases du mouvement du logiciel libre."),
        Question(11490, "En quelle année BSD a-t-il été créé?", listOf("1977", "1975", "1979", "1981"), 0, "Technologie", Difficulty.HARD, explanation = "BSD, acronyme de Berkeley Software Distribution, a été créé en 1977 par l'université de Californie à Berkeley comme une version améliorée d'Unix."),
        Question(11491, "En quelle année System V a-t-il été créé?", listOf("1983", "1981", "1985", "1987"), 0, "Technologie", Difficulty.HARD, explanation = "System V est une version majeure du système d'exploitation UNIX, développée par AT&T et publiée en 1983."),
        Question(11492, "En quelle année DOS a-t-il été créé?", listOf("1981", "1979", "1983", "1985"), 0, "Technologie", Difficulty.HARD, explanation = "MS-DOS a été développé par Microsoft pour IBM et lancé en 1981 avec le premier PC IBM."),
        Question(11493, "Qui a créé DOS?", listOf("Tim Paterson", "Bill Gates", "Steve Jobs", "Mark Zuckerberg"), 0, "Technologie", Difficulty.HARD, explanation = "Tim Paterson a écrit le système d'exploitation 86-DOS en 1980 pour Seattle Computer Products, que Microsoft a ensuite acheté et rebaptisé MS-DOS."),
        Question(11494, "En quelle année Windows a-t-il été créé?", listOf("1985", "1983", "1987", "1989"), 0, "Technologie", Difficulty.EASY, explanation = "Microsoft a lancé Windows 1.0 le 20 novembre 1985, marquant le début de son système d'exploitation graphique pour PC."),
        Question(11495, "En quelle année macOS a-t-il été créé?", listOf("2001", "1999", "2003", "2005"), 0, "Technologie", Difficulty.HARD, explanation = "macOS, alors nommé Mac OS X, a été lancé en mars 2001, succédant au Mac OS 9 et marquant le passage à un système basé sur Unix."),
        Question(11496, "En quelle année OS X a-t-il été renommé macOS?", listOf("2016", "2014", "2018", "2020"), 0, "Technologie", Difficulty.HARD, explanation = "Apple a renommé OS X en macOS en 2016 pour aligner son système d'exploitation de bureau avec ses autres systèmes (iOS, watchOS, tvOS) et simplifier la nomenclature."),
        Question(11497, "En quelle année iOS a-t-il été lancé?", listOf("2007", "2005", "2009", "2011"), 0, "Technologie", Difficulty.EASY, explanation = "iOS a été dévoilé par Apple le 9 janvier 2007, en même temps que le premier iPhone, dont il était le système d'exploitation."),
        Question(11498, "En quelle année Android a-t-il été créé?", listOf("2003", "2001", "2005", "2007"), 0, "Technologie", Difficulty.MEDIUM, explanation = "Android a été fondé en 2003 par Andy Rubin, Rich Miner, Nick Sears et Chris White. Le système d'exploitation a ensuite été racheté par Google en 2005."),
        Question(11499, "Qui a créé Android?", listOf("Andy Rubin", "Mark Zuckerberg", "Steve Jobs", "Bill Gates"), 0, "Technologie", Difficulty.MEDIUM, explanation = "Andy Rubin a fondé Android Inc. en 2003, avant que Google ne rachète la startup en 2005 pour développer le système d'exploitation mobile.")
    )
